    function objectBox(o){if(['environmental-node','environmental-zone','environmental-pyramid','environmental-label'].includes(o.type))return{x:o.x,y:o.y,w:o.width,h:o.height};if(['environmental-link','environmental-arrow'].includes(o.type))return{x:Math.min(o.x1||0,o.x2||0),y:Math.min(o.y1||0,o.y2||0),w:Math.max(1,Math.abs((o.x2||0)-(o.x1||0))),h:Math.max(1,Math.abs((o.y2||0)-(o.y1||0)))};if(o.type==='text')return{x:o.x,y:o.y-o.fontSize,w:Math.max(100,String(o.text||'').length*o.fontSize*.55),h:o.fontSize+10};return null;}
